const MAX_DIRECT_UPLOAD = 2 * 1024 * 1024 * 1024

type Server = {
  id:string; name:string; nodeId?:string; loader:string; mcVersion:string; loaderVersion?:string|null;
  status:string; port:number; memoryMb:number; playerCount:number; installProgress:number;
  installError?:string|null; worldName?:string; publicHost?:string; connectionAddress?:string
}
type NodeInfo = { id:string; name:string; status:string; lastHeartbeat:string|null; cpuPercent:number; memoryUsedMb:number; memoryTotalMb:number; diskUsedGb:number; diskTotalGb:number }
type LogRow = { id:number; serverId:string; line:string; createdAt:string }
type WorldRow = { id:string; serverId:string; name:string; isActive:boolean; sizeMb:number; seed?:string|null; lastBackupAt?:string|null }
type Permission = { userId:string; serverId:string; canStart:boolean; canStop:boolean; canRestart:boolean; canConsole:boolean; canFiles:boolean; canBackup:boolean; canReset:boolean; canViewLostItems:boolean; canManageLostItems:boolean; sections?:string[] }
type Member = { id:string; name:string; email:string; role:string; approved:boolean }
type Operation = { id:number; serverId:string; operation:string; status:string; message?:string|null; createdAt:string }
type Panel = { servers:Server[]; nodes:NodeInfo[]; logs:LogRow[]; worlds:WorldRow[]; users:Member[]; permissions:Permission[]; currentPermission?:Permission|null; allowedSections?:string[]; operations:Operation[]; schedules?:ScheduleRow[]; databases?:ManagedDatabaseRow[]; sftp?:SftpRow|null; actor?:{id:string;name:string;email:string;role:string} }
type BackupRow = { id:string; worldId:string; worldName:string; blobPathname:string; sizeMb:number; createdAt:string; status?:'queued'|'running'|'completed'|'failed'; progress?:number }
type ScheduleRow = { id:string; serverId:string; name:string; taskType:'restart'|'backup'|'log-cleanup'; cadence:'daily'|'weekly'|'interval'; timeOfDay?:string|null; weekday?:number|null; intervalMinutes?:number|null; timezoneOffsetMinutes:number; enabled:boolean; payload?:{retentionDays?:number}; lastRunAt?:string|null; nextRunAt:string; createdAt:string }
type ManagedDatabaseRow = { id:string; serverId:string; engine:string; databaseName:string; databaseUser:string; host:string; port:number; credentialsPath?:string|null; status:string; lastError?:string|null; createdAt:string }
type SftpRow = { username:string; port:number; rootPath:string; status:string; lastError?:string|null; lastTestAt?:string|null; passwordRotatedAt?:string|null; disabledAt?:string|null; createdAt?:string|null; updatedAt?:string|null }


async function readJson(response:Response){
  const text = await response.text()
  try { return text ? JSON.parse(text) : {} }
  catch { throw new Error(response.ok ? 'Sunucudan geçersiz yanıt alındı' : `Sunucu hatası (${response.status}): ${text.slice(0,180)}`) }
}
const fetcher=(url:string)=>fetch(url,{cache:'no-store',headers:{accept:'application/json'}}).then(async r=>{const d=await readJson(r);if(!r.ok)throw new Error(d.error??'İstek başarısız');return d})

async function directUploadFile(serverId:string,file:File,category:string,onProgress?:(percent:number)=>void){
  const started=await fetch('/api/direct-upload',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'start',serverId,filename:file.name,size:file.size,category})})
  const s=await readJson(started) as {error?:string;uploadId?:string;commandId?:string;chunkSize?:number}
  if(!started.ok||!s.uploadId||!s.commandId||!s.chunkSize) throw new Error(s.error??`Yükleme başlatılamadı (${started.status})`)
  const uploadId=s.uploadId; const commandId=s.commandId; const chunkSize=s.chunkSize
  const total=Math.ceil(file.size/chunkSize)
  const statusResponse=await fetch(`/api/direct-upload?commandId=${encodeURIComponent(commandId)}&uploadId=${encodeURIComponent(uploadId)}`,{cache:'no-store'}); const statusData=await readJson(statusResponse) as {receivedParts?:number[];receivedBytes?:number}; const received=new Set(statusData.receivedParts??[])
  let uploadedBytes=Number(statusData.receivedBytes??0); let nextPart=0; const concurrency=4; onProgress?.(Math.round(uploadedBytes/file.size*100))
  const uploadPart=async(part:number)=>{const chunk=file.slice(part*chunkSize,Math.min(file.size,(part+1)*chunkSize));let last='';for(let attempt=0;attempt<5;attempt++){try{const r=await fetch(`/api/direct-upload?commandId=${encodeURIComponent(commandId)}&uploadId=${encodeURIComponent(uploadId)}&part=${part}`,{method:'PUT',headers:{'content-type':'application/octet-stream'},body:chunk});const d=await readJson(r);if(!r.ok)throw new Error(d.error??`Parça ${part+1} yüklenemedi`);last='';break}catch(error){last=error instanceof Error?error.message:'Parça yüklenemedi';if(attempt<4)await new Promise(resolve=>setTimeout(resolve,500*2**attempt))}}if(last)throw new Error(last);uploadedBytes+=chunk.size;onProgress?.(Math.round(uploadedBytes/file.size*100))}
  const worker=async()=>{while(true){const part=nextPart++;if(part>=total)return;if(received.has(part))continue;await uploadPart(part)}}
  await Promise.all(Array.from({length:Math.min(concurrency,total)},()=>worker()))
  const done=await fetch('/api/direct-upload',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'complete',commandId,uploadId})})
  const result=await readJson(done); if(!done.ok)throw new Error(result.error??'Yükleme tamamlanamadı'); return result
}

const nav=[
  ['overview','Genel Bakış',Gamepad2],['settings','Ayarlar',Settings2],['console','Konsol',Terminal],['logs','Günlük',FileText],
  ['players','Oyuncular',Users],['software','Yazılım',Wrench],['files','Dosyalar',Folder],['bulk-download','Toplu İndirme',Download],['worlds','Dünyalar',Globe2],
  ['backups','Yedekler',RotateCcw],['network','Ağ / Portlar',Network],['integrations','Entegrasyonlar',Zap],['schedules','Zamanlamalar',Clock3],['databases','Veritabanları',Database],['access','Erişim',Shield],['security','Güvenlik',ShieldCheck]
] as const

export default function ServerPage(){
  const {id}=useParams<{id:string}>(); const router=useRouter(); const searchParams=useSearchParams()
  const {data,error,mutate}=useSWR<Panel>(`/api/panel?serverId=${id}`,fetcher,{refreshInterval:3000})
  const server=data?.servers.find(s=>s.id===id); const node=data?.nodes?.[0]
  const manager=data?.actor?.role==='manager'; const permission=data?.currentPermission??undefined
  const allowedSections=useMemo(()=>data?.allowedSections?.length?data.allowedSections:(manager?nav.map(([key])=>key):['overview','logs']),[data?.allowedSections,manager])
  const visibleNav=useMemo(()=>nav.filter(([key])=>key==='security'?manager:key==='bulk-download'?(manager||allowedSections.includes('files')):allowedSections.includes(key)),[allowedSections,manager])
  const {data:backupData,error:backupError,mutate:mutateBackups}=useSWR<{backups:BackupRow[]}>(allowedSections.includes('backups')?`/api/backups?serverId=${id}`:null,fetcher,{refreshInterval:5000})
  const [section,setSection]=useState<(typeof nav)[number][0]>('overview'); const [open,setOpen]=useState(false); const [busy,setBusy]=useState(false); const [notice,setNotice]=useState('')
  const [settingsTab,setSettingsTab]=useState<'general'|'security'|'performance'|'anticheat'|'backup'>('general'); const [selectedUserId,setSelectedUserId]=useState('')
  const [uiSecurity,setUiSecurity]=useState({startupScan:true,bruteForce:true,commandLog:true,fileFilter:true,proxyControl:true,movement:true,reach:true,speed:true,xray:true,crashRecovery:true,performanceMonitor:true,autoCleanup:true})
  const [motd,setMotd]=useState('BlockCtrl sunucusu'); const [maxPlayers,setMaxPlayers]=useState('20'); const [onlineMode,setOnlineMode]=useState(false); const [gamemode,setGamemode]=useState('survival'); const [difficulty,setDifficulty]=useState('easy'); const [pvp,setPvp]=useState(true); const [viewDistance,setViewDistance]=useState('10'); const [simulationDistance,setSimulationDistance]=useState('10'); const [spawnProtection,setSpawnProtection]=useState('16'); const [allowFlight,setAllowFlight]=useState(false); const [whitelist,setWhitelist]=useState(false)
  const [playerName,setPlayerName]=useState(''); const [newPort,setNewPort]=useState(''); const [worldName,setWorldName]=useState('world_2'); const [softwareLoader,setSoftwareLoader]=useState('paper'); const [softwareVersion,setSoftwareVersion]=useState('1.21.1'); const [softwareLoaderVersion,setSoftwareLoaderVersion]=useState(''); const [consoleLine,setConsoleLine]=useState('')
  const [scheduleName,setScheduleName]=useState('Gece yeniden başlat'); const [scheduleTask,setScheduleTask]=useState<'restart'|'backup'|'log-cleanup'>('restart'); const [scheduleCadence,setScheduleCadence]=useState<'daily'|'weekly'|'interval'>('daily'); const [scheduleTime,setScheduleTime]=useState('04:00'); const [scheduleWeekday,setScheduleWeekday]=useState('0'); const [scheduleInterval,setScheduleInterval]=useState('60'); const [retentionDays,setRetentionDays]=useState('30')
  const [databaseName,setDatabaseName]=useState('minecraft'); const [databaseUser,setDatabaseUser]=useState('mc_user')
  const logs=useMemo(()=>data?.logs?.filter(l=>l.serverId===id).slice(-150)??[],[data,id])
  const playerNames=useMemo(()=>{for(const row of [...logs].reverse()){const m=row.line.match(/There are \d+ of a max of \d+ players online:?\s*(.*)$/i);if(m){return m[1].split(',').map(x=>x.trim()).filter(Boolean)}}return []},[logs])
  const errorCount=useMemo(()=>logs.filter(row=>/\bERROR\b|Exception|failed|fatal/i.test(row.line)).length,[logs]); const warningCount=useMemo(()=>logs.filter(row=>/\bWARN(?:ING)?\b/i.test(row.line)).length,[logs])
  const activeSchedules=(data?.schedules??[]).filter(s=>s.enabled).length; const selectedUser=data?.users?.find(u=>u.id===selectedUserId)??data?.users?.[0]; const selectedPermission=selectedUser?data?.permissions?.find(p=>p.userId===selectedUser.id):undefined
  const canStart=!!manager||!!permission?.canStart; const canStop=!!manager||!!permission?.canStop; const canRestart=!!manager||!!permission?.canRestart; const canConsole=!!manager||!!permission?.canConsole; const canFiles=!!manager||!!permission?.canFiles; const canBackup=!!manager||!!permission?.canBackup; const canReset=!!manager||!!permission?.canReset
  useEffect(()=>{if(visibleNav.length&&!visibleNav.some(([key])=>key===section))setSection(visibleNav[0][0])},[visibleNav,section])
  useEffect(()=>{const wanted=searchParams.get('section');if(wanted&&visibleNav.some(([key])=>key===wanted))setSection(wanted as (typeof nav)[number][0])},[searchParams,visibleNav])
  useEffect(()=>{if(manager&&!selectedUserId&&data?.users?.length)setSelectedUserId(data.users[0].id)},[manager,selectedUserId,data?.users])

  async function command(type:string,payload:Record<string,unknown>={},destructive=false){
    if(!server)return; let confirmName: string|undefined
    if(destructive){confirmName=prompt(`Onaylamak için “${server.name}” yazın.`)??undefined;if(confirmName!==server.name)return}
    setBusy(true);setNotice('')
    try{const r=await fetch('/api/panel',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'command',serverId:id,type,payload:{...payload,confirm:destructive?true:payload.confirm},confirm:confirmName})});const d=await readJson(r);if(!r.ok)throw new Error(d.error??'İşlem başarısız');setNotice('İşlem kuyruğa alındı.');await mutate()}
    catch(e){setNotice(e instanceof Error?e.message:'İşlem başarısız')} finally{setBusy(false)}
  }
  async function panelAction(action:string,payload:Record<string,unknown>={}){
    setBusy(true);setNotice('')
    try{
      const r=await fetch('/api/panel',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action,serverId:id,...payload})})
      const d=await readJson(r);if(!r.ok)throw new Error(d.error??'İşlem başarısız')
      setNotice('İşlem başarıyla kaydedildi.');await mutate();return d
    }catch(e){setNotice(e instanceof Error?e.message:'İşlem başarısız');return null}finally{setBusy(false)}
  }
  async function backupAction(type:string,payload:Record<string,unknown>={},requiresConfirm=false){
    if(requiresConfirm&&prompt('Bu işlem için CONFIRM yazın.')!=='CONFIRM')return;setBusy(true);setNotice('')
    try{const r=await fetch('/api/backups',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({serverId:id,type,payload,...payload,confirm:requiresConfirm})});const d=await readJson(r);if(!r.ok)throw new Error(d.error??'Yedek işlemi başarısız');setNotice('Yedek işlemi kuyruğa alındı.');await mutateBackups();await mutate()}
    catch(e){setNotice(e instanceof Error?e.message:'Yedek işlemi başarısız')}finally{setBusy(false)}
  }
  async function permissionAction(userId:string,grant:boolean){setBusy(true);setNotice('');try{const r=await fetch('/api/panel',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(grant?{action:'set-permission',serverId:id,userId,canStart:true,canStop:true,canRestart:true,canConsole:true,canFiles:true,canBackup:true,canReset:true,canViewLostItems:true,canManageLostItems:true}:{action:'remove-permission',serverId:id,userId})});const d=await readJson(r);if(!r.ok)throw new Error(d.error??'Erişim güncellenemedi');setNotice(grant?'Kullanıcıya tam erişim verildi.':'Kullanıcının erişimi kaldırıldı.');await mutate()}catch(e){setNotice(e instanceof Error?e.message:'Erişim güncellenemedi')}finally{setBusy(false)}}
  const saveSettings=()=>command('set-properties',{'max-players':Math.max(1,Math.min(500,Number(maxPlayers)||20)),motd:motd.slice(0,150),'online-mode':onlineMode,gamemode,difficulty,pvp,'view-distance':Math.max(2,Math.min(32,Number(viewDistance)||10)),'simulation-distance':Math.max(2,Math.min(32,Number(simulationDistance)||10)),'spawn-protection':Math.max(0,Math.min(256,Number(spawnProtection)||16)),'allow-flight':allowFlight,'white-list':whitelist})
  async function upload(e:React.ChangeEvent<HTMLInputElement>,category:string){const file=e.target.files?.[0];if(!file)return;if(file.size>MAX_DIRECT_UPLOAD){setNotice('Dosya 2 GB sınırını aşamaz.');e.target.value='';return}setBusy(true);try{await directUploadFile(id,file,category,p=>{const uploaded=Math.round(file.size*p/100/1048576);setNotice(`${file.name} yükleniyor: %${p} · ${uploaded} / ${(file.size/1048576).toFixed(0)} MB · 4 paralel parça`)});setNotice(`${file.name} sunucuya yüklendi.`);await mutate()}catch(err){setNotice(err instanceof Error?err.message:'Dosya yüklenemedi')}finally{setBusy(false);e.target.value=''}}
  async function uploadWorldFile(file:File){if(file.size>MAX_DIRECT_UPLOAD){setNotice('Dünya ZIP dosyası 2 GB sınırını aşamaz.');return}setBusy(true);try{await directUploadFile(id,file,'worlds',p=>{const uploaded=Math.round(file.size*p/100/1048576);setNotice(`${file.name} yükleniyor: %${p} · ${uploaded} / ${(file.size/1048576).toFixed(0)} MB`)});setNotice(`${file.name} dünya paketi sunucuya yüklendi.`);await mutate()}catch(err){setNotice(err instanceof Error?err.message:'Dünya yüklenemedi')}finally{setBusy(false)}}
  function downloadLogs(){const body=logs.map(l=>`[${new Date(l.createdAt).toLocaleString('tr-TR')}] ${l.line}`).join('\n');const url=URL.createObjectURL(new Blob([body],{type:'text/plain'}));const a=document.createElement('a');a.href=url;a.download=`${server?.name??'server'}-latest.log`;a.click();URL.revokeObjectURL(url)}

  if(error)return <main className="p-8 text-red-300">{error.message}</main>; if(!server)return <main className="p-8">Sunucu bulunamadı.</main>
  const running=server.status==='running'; const diskPct=node?.diskTotalGb?Math.round(node.diskUsedGb/node.diskTotalGb*100):0; const ramPct=node?.memoryTotalMb?Math.round(node.memoryUsedMb/node.memoryTotalMb*100):0

  const connectionAddress=server.connectionAddress??`${server.publicHost??'IP bekleniyor'}:${server.port}`
  const recentLogs=[...logs].reverse().slice(0,24)
  const lastBackup=backupData?.backups?.[0]
  const onlineNode=node?.status==='online'
  const uptimeText=running&&logs.length?formatDuration(Date.now()-new Date(logs[0].createdAt).getTime()):'—'
  const securityScore=Math.max(70,Math.min(100,100-errorCount*2-warningCount))

  return <main className="min-h-svh bg-[#06100d] text-slate-100 selection:bg-emerald-400/30">
    <div className="flex min-h-svh">
      <aside className={`${open?'translate-x-0':'-translate-x-full'} fixed inset-y-0 left-0 z-40 flex w-[220px] shrink-0 flex-col border-r border-emerald-950/80 bg-[radial-gradient(circle_at_10%_10%,rgba(16,185,129,.09),transparent_35%),#0a1b15] px-2.5 py-3 shadow-2xl transition-transform lg:static lg:translate-x-0`}>
        <div className="flex items-start justify-between px-2 pb-5 pt-1">
          <div><p className="text-[11px] font-semibold uppercase tracking-[.24em] text-emerald-400">BLOCKCTRL</p><h1 className="mt-1 text-[16px] font-semibold text-white">{server.name}</h1></div>
          <Button size="icon" variant="ghost" className="lg:hidden" onClick={()=>setOpen(false)}><X className="size-4"/></Button>
        </div>
        <nav className="flex flex-1 flex-col gap-0.5 overflow-y-auto pb-3">{visibleNav.map(([key,label,Icon])=><button key={key} onClick={()=>{setSection(key);setOpen(false)}} className={`group flex min-h-10 items-center gap-3 rounded-md px-3 text-left text-[13px] font-semibold transition ${section===key?'bg-gradient-to-r from-emerald-600 to-emerald-400 text-emerald-950 shadow-[0_0_24px_rgba(16,185,129,.18)]':'text-slate-100 hover:bg-emerald-950/45'}`}><Icon className="size-[15px] shrink-0"/>{label}</button>)}</nav>
        <button onClick={()=>router.push('/')} className="mb-3 flex min-h-10 items-center gap-3 rounded-md px-3 text-left text-[13px] font-semibold text-slate-200 hover:bg-emerald-950/45"><ArrowLeft className="size-[15px]"/>Sunuculara dön</button>
        <div className="rounded-xl border border-emerald-900/60 bg-black/15 p-3">
          <div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-lg bg-emerald-500/10 text-emerald-300"><Box className="size-5"/></div><div className="min-w-0"><p className="truncate text-xs font-semibold text-white">{server.name}</p><p className="mt-1 flex items-center gap-1.5 text-[11px] text-emerald-300"><span className={`size-2 rounded-full ${running?'bg-emerald-400':'bg-slate-500'}`}/>{running?'Çevrimiçi':'Kapalı'}</p><p className="mt-0.5 truncate text-[10px] text-slate-500">{server.loader.toLowerCase()} {server.mcVersion}</p></div></div>
        </div>
      </aside>

      <section className="min-w-0 flex-1">
        <header className="sticky top-0 z-30 flex h-[60px] items-center justify-between border-b border-emerald-950/70 bg-[#07130f]/95 px-4 backdrop-blur-xl lg:px-5">
          <div className="flex items-center gap-3"><Button size="icon" variant="ghost" className="lg:hidden" onClick={()=>setOpen(true)}><Menu className="size-5"/></Button><div><p className="text-[11px] text-slate-500">Sunucu yönetimi / {nav.find(n=>n[0]===section)?.[1]}</p><h2 className="text-[15px] font-semibold text-white">{server.name}</h2></div></div>
          <div className="flex items-center gap-2"><SupportCenter/>{canStart&&<Button size="sm" className="h-8 bg-emerald-600 px-3 text-xs text-emerald-950 hover:bg-emerald-500" onClick={()=>command('start')} disabled={busy||running}><Play className="mr-1 size-3.5"/>Başlat</Button>}{canStop&&<Button size="sm" variant="outline" className="h-8 border-emerald-950/80 bg-black/10 px-3 text-xs" onClick={()=>command('stop')} disabled={busy||!running}><Square className="mr-1 size-3.5"/>Durdur</Button>}{canRestart&&<Button size="sm" variant="outline" className="h-8 border-emerald-950/80 bg-black/10 px-3 text-xs" onClick={()=>command('restart')} disabled={busy||!running}><RefreshCw className="mr-1 size-3.5"/>Restart</Button>}</div>
        </header>

        <div className="mx-auto w-full max-w-[1540px] space-y-4 p-4 lg:p-5">
          {notice&&<div role="status" className="rounded-lg border border-emerald-500/25 bg-emerald-950/35 px-4 py-3 text-sm text-emerald-200">{notice}</div>}

          {section==='overview'&&<>
            <PageHeading title="Genel Bakış" text="Sunucu durumu, sistem kaynakları ve güvenlik bilgilerinizi buradan takip edin."/>
            <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
              <MetricCard icon={ServerIcon} title="Durum" value={running?'Çevrimiçi':'Kapalı'} detail={`${server.loader.toLowerCase()} ${server.mcVersion}`} accent={running}/>
              <MetricCard icon={Users} title="Oyuncular" value={`${server.playerCount} / ${maxPlayers}`} detail="Anlık oyuncu sayısı" progress={Math.min(100,Math.round(server.playerCount/Math.max(1,Number(maxPlayers))*100))}/>
              <MetricCard icon={Cpu} title="CPU" value={node?`%${Math.round(node.cpuPercent)}`:'—'} detail={node?.name??'Node metriği bekleniyor'} progress={node?Math.round(node.cpuPercent):0}/>
              <MetricCard icon={HardDrive} title="RAM" value={node?`${(node.memoryUsedMb/1024).toFixed(1)} / ${(node.memoryTotalMb/1024).toFixed(1)} GB`:`${server.memoryMb} MB`} detail={node?`%${ramPct} kullanım`:'Sunucu limiti'} progress={ramPct}/>
            </div>
            <div className="grid gap-3 xl:grid-cols-[1.2fr_1fr_.75fr]">
              <PanelCard><div className="grid gap-3 sm:grid-cols-2"><MiniStat icon={HardDrive} label="Disk" value={node?.diskTotalGb?`${node.diskUsedGb.toFixed(1)} / ${node.diskTotalGb.toFixed(1)} GB`:'—'} sub={node?.diskTotalGb?`%${diskPct} kullanım`:'Disk metriği bekleniyor'}/><MiniStat icon={Globe2} label="IP / Adres" value={connectionAddress} sub="Oyuncuların bağlanacağı adres" mono/></div></PanelCard>
              <PanelCard title="Hızlı işlemler" subtitle="Sık kullanılan işlemlere hızlıca erişin."><div className="grid grid-cols-2 gap-2"><QuickAction icon={Play} label="Başlat" onClick={()=>command('start')} disabled={!canStart||busy||running}/><QuickAction icon={Square} label="Durdur" onClick={()=>command('stop')} disabled={!canStop||busy||!running}/><QuickAction icon={Terminal} label="Konsola git" onClick={()=>setSection('console')}/><QuickAction icon={Folder} label="Dosyalara git" onClick={()=>setSection('files')}/><QuickAction icon={Shield} label="Güvenlik ayarları" onClick={()=>setSection('security')} disabled={!manager}/><QuickAction icon={RotateCcw} label="Yedek al" onClick={()=>backupAction('backup',{kind:'full',label:'manual'})} disabled={!canBackup||busy}/></div></PanelCard>
              <PanelCard title="Sunucu sağlığı" subtitle="Koruma ve servis durumu."><HealthRow label="Hile koruması" value={securityScore}/><HealthRow label="Dosya taraması" value={errorCount?92:100}/><HealthRow label="Otomatik yedekleme" value={lastBackup?100:82}/><HealthRow label="Performans durumu" value={Math.max(0,100-Math.round(node?.cpuPercent??0))}/></PanelCard>
            </div>
            <div className="grid gap-3 xl:grid-cols-[1.15fr_.85fr]">
              <PanelCard title="Güvenlik Merkezi" subtitle="Sunucunuzun güvenlik durumu ve koruma sistemleri." action={<button onClick={()=>setSection('security')} className="text-[11px] text-slate-300 hover:text-white">Güvenlik ayarlarına git →</button>}><div className="grid gap-1"><StatusLine icon={Shield} label="Güvenlik duvarı" sub="Zararlı bağlantılara karşı korunur" status="Aktif"/><StatusLine icon={Network} label="DDoS koruması" sub="Saldırılara karşı trafik filtreleme" status="Aktif"/><StatusLine icon={FileText} label="Dosya taraması" sub="Sunucu dosyaları düzenli olarak taranır" status="Aktif"/><StatusLine icon={Gamepad2} label="Hile koruması" sub="Oyun içi hilelere karşı koruma" status="Aktif"/><StatusLine icon={KeyRound} label="Erişim denetimi" sub="Yetkili kullanıcılar ve IP kontrolleri" status="Güvenli"/></div></PanelCard>
              <PanelCard title="Uyarılar ve öneriler" subtitle="Sunucunuz için önemli uyarılar ve iyileştirme önerileri."><NoticeRow tone={onlineMode?'info':'warn'} title={onlineMode?'Premium doğrulama açık':'Cracked giriş tespit edildi'} text={onlineMode?'Kimlik doğrulama etkin.':'Offline mod açıkken whitelist ve ek kimlik doğrulama kullanmanız önerilir.'}/><NoticeRow tone="info" title="Whitelist kullanımını değerlendirin" text={whitelist?'Whitelist şu anda açık.':'Sunucuyu yalnızca yetkili oyunculara açmak için whitelist etkinleştirilebilir.'}/>{!lastBackup&&<NoticeRow tone="info" title="Otomatik yedekleme ayarlayın" text="Veri kaybını önlemek için düzenli bir yedekleme planı oluşturun."/>}</PanelCard>
            </div>
            <PanelCard title="Son işlemler" subtitle="Sunucuda gerçekleşen son işlemler." action={<button onClick={()=>setSection('logs')} className="text-[11px] text-slate-300 hover:text-white">Tüm günlükleri görüntüle →</button>}><OperationTable rows={(data?.operations??[]).slice(0,6)}/></PanelCard>
          </>}

          {section==='settings'&&<>
            <PageHeading title="Ayarlar" text="Sunucu, güvenlik, performans, JVM, loader, yedekleme ve diğer gelişmiş seçenekleri tek merkezden yönetin."/>
            <ServerSettingsCenter serverId={id} loader={server.loader} running={running} canEdit={canReset} onNavigate={target=>setSection(target as (typeof nav)[number][0])}/>
          </>}

          {section==='console'&&<>
            <PageHeading title="Konsol" text={`${server.loader} sunucunuzun canlı çıktısını görüntüleyin ve komut gönderin.`} right={<div className="flex items-center gap-2 rounded-xl border border-emerald-950/70 bg-[#0c1b15] px-3 py-2 text-xs"><span className={`size-2.5 rounded-full ${running?'bg-emerald-400':'bg-slate-500'}`}/><div><b className={running?'text-emerald-300':'text-slate-400'}>{running?'Çevrimiçi':'Kapalı'}</b><div className="text-[10px] text-slate-500">Son güncelleme: {node?.lastHeartbeat?new Date(node.lastHeartbeat).toLocaleString('tr-TR'):'—'}</div></div></div>}/>
            <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><CompactMetric label="Durum" value={running?'Çevrimiçi':'Kapalı'} sub={`${server.loader} ${server.mcVersion}`} good={running}/><CompactMetric label="CPU" value={node?`%${Math.round(node.cpuPercent)}`:'—'} sub={node?.name??'Node'}/><CompactMetric label="RAM" value={node?`${(node.memoryUsedMb/1024).toFixed(1)} / ${(node.memoryTotalMb/1024).toFixed(1)} GB`:'—'} sub={`%${ramPct} kullanım`}/><CompactMetric label="Disk" value={node?.diskTotalGb?`${node.diskUsedGb.toFixed(1)} / ${node.diskTotalGb.toFixed(1)} GB`:'—'} sub={`%${diskPct} kullanım`}/><CompactMetric label="Node" value={node?.name??'BlockCtrl sunucusu'} sub={onlineNode?'Bağlı':'Bağlantı bekleniyor'}/><CompactMetric label="Çalışma süresi" value={uptimeText} sub={running?'Sunucu aktif':'Sunucu kapalı'}/></div>
            <PanelCard className="p-0 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-2 border-b border-emerald-950/70 p-3"><div className="flex rounded-lg border border-emerald-950/80 bg-black/10 p-0.5"><TabPill active icon={Terminal} label="Sunucu Konsolu"/><TabPill icon={Settings2} label="Agent"/><TabPill icon={Database} label="Sistem"/></div><div className="flex gap-2"><select className="h-8 rounded-md border border-emerald-950/80 bg-[#0a1712] px-3 text-xs"><option>Tüm seviyeler</option><option>INFO</option><option>WARN</option><option>ERROR</option></select><div className="relative hidden md:block"><Search className="absolute left-2.5 top-2 size-3.5 text-slate-500"/><input className="h-8 w-72 rounded-md border border-emerald-950/80 bg-[#0a1712] pl-8 pr-3 text-xs outline-none focus:border-emerald-500/50" placeholder="Konsolda ara..."/></div><Button size="sm" variant="outline" className="h-8" onClick={()=>setNotice('Konsol görünümü temizlendi; sunucu günlükleri silinmedi.')}><Trash2 className="mr-1 size-3.5"/>Temizle</Button></div></div><div className="h-[390px] overflow-auto bg-[#06100d] p-4 font-mono text-[12px] leading-[1.75]">{logs.length?logs.map(l=><div key={l.id} className={/ERROR|Exception|fatal/i.test(l.line)?'text-red-300':/WARN/i.test(l.line)?'text-amber-300':'text-slate-300'}><span className="text-slate-600">[{new Date(l.createdAt).toLocaleTimeString('tr-TR')}]</span> {l.line}</div>):<span className="text-slate-500">Henüz konsol çıktısı yok.</span>}</div><form className="flex gap-2 border-t border-emerald-950/70 p-3" onSubmit={e=>{e.preventDefault();if(consoleLine.trim()){void command('console',{line:consoleLine.trim()});setConsoleLine('')}}}><div className="flex min-w-0 flex-1 items-center rounded-md border border-emerald-950/80 bg-[#0a1712]"><Terminal className="ml-3 size-4 text-slate-500"/><input className="h-9 min-w-0 flex-1 bg-transparent px-3 text-xs outline-none" value={consoleLine} onChange={e=>setConsoleLine(e.target.value)} placeholder={canConsole?'komut girin...':'Salt okunur konsol'} disabled={!running||!canConsole}/></div><Button className="h-9 bg-emerald-600 text-emerald-950 hover:bg-emerald-500" disabled={!running||!canConsole||!consoleLine.trim()}><Send className="mr-2 size-4"/>Gönder</Button></form><div className="border-t border-emerald-950/70 px-3 py-3"><p className="mb-2 text-xs font-semibold">Hızlı komutlar</p><div className="flex flex-wrap gap-2">{['list','say Merhaba','save-all','whitelist on','stop'].map(cmd=><button key={cmd} disabled={!running||!canConsole} onClick={()=>command('console',{line:cmd})} className="rounded-md border border-emerald-950/80 bg-black/10 px-3 py-1.5 text-xs hover:bg-emerald-950/30 disabled:opacity-40">{cmd}</button>)}</div></div></PanelCard>
          </>}

          {section==='logs'&&<>
            <PageHeading title="Günlük" text="Sunucu olaylarını, hataları ve sistem kayıtlarını görüntüleyin."/>
            <div className="grid gap-3 xl:grid-cols-[1fr_310px]">
              <PanelCard className="p-0 overflow-hidden"><div className="flex flex-wrap items-center gap-2 border-b border-emerald-950/70 p-3"><TabPill active icon={Activity} label="Sunucu"/><TabPill icon={Users} label="Agent"/><TabPill icon={AlertTriangle} label="Hata"/><TabPill icon={FileText} label="Crash"/><div className="flex-1"/><div className="relative min-w-[220px] flex-1 md:max-w-md"><Search className="absolute left-2.5 top-2.5 size-3.5 text-slate-500"/><input className="h-9 w-full rounded-md border border-emerald-950/80 bg-[#0a1712] pl-8 pr-3 text-xs outline-none" placeholder="Günlüklerde ara..."/></div><select className="h-9 rounded-md border border-emerald-950/80 bg-[#0a1712] px-3 text-xs"><option>Tüm seviyeler</option><option>INFO</option><option>WARN</option><option>ERROR</option></select><Button size="sm" variant="outline" className="h-9" onClick={downloadLogs}><Download className="mr-1 size-3.5"/>İndir</Button></div><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-xs"><thead className="bg-white/[.025] text-slate-400"><tr><th className="px-4 py-3 font-medium">Zaman</th><th className="px-4 py-3 font-medium">Seviye</th><th className="px-4 py-3 font-medium">Kaynak</th><th className="px-4 py-3 font-medium">Olay</th><th className="px-4 py-3 font-medium">Durum</th></tr></thead><tbody>{recentLogs.map(row=>{const parsed=parseLog(row.line);return <tr key={row.id} className="border-t border-emerald-950/60"><td className="px-4 py-2.5 text-slate-400">{new Date(row.createdAt).toLocaleString('tr-TR')}</td><td className="px-4 py-2.5"><LevelBadge level={parsed.level}/></td><td className="px-4 py-2.5 text-slate-300">{parsed.source}</td><td className="max-w-[520px] truncate px-4 py-2.5 text-slate-300">{parsed.message}</td><td className="px-4 py-2.5"><span className="inline-flex items-center gap-1.5 text-slate-400"><span className="size-1.5 rounded-full bg-emerald-400"/>Tamamlandı</span></td></tr>})}{!recentLogs.length&&<tr><td colSpan={5} className="p-8 text-center text-slate-500">Henüz günlük kaydı yok.</td></tr>}</tbody></table></div><div className="flex items-center justify-between border-t border-emerald-950/60 px-4 py-3 text-[11px] text-slate-500"><span>{logs.length} kayıt gösteriliyor</span><Button size="sm" variant="outline" className="h-7" onClick={()=>mutate()}><RefreshCw className="mr-1 size-3"/>Yenile</Button></div></PanelCard>
              <div className="space-y-3"><SideStat icon={FileText} label="Toplam günlük kaydı" value={String(logs.length)} sub="Son alınan kayıtlar"/><SideStat icon={AlertTriangle} label="Son hata" value={errorCount?`${errorCount} hata`:'Yok'} sub={errorCount?'İnceleme önerilir':'Hata görünmüyor'} danger={!!errorCount}/><SideStat icon={FileText} label="Crash raporları" value={String(logs.filter(x=>/crash|tick loop/i.test(x.line)).length)} sub="Mevcut günlüklerde"/><SideStat icon={HardDrive} label="Depolama kullanımı" value={node?.diskTotalGb?`${node.diskUsedGb.toFixed(1)} GB`:'—'} sub={node?.diskTotalGb?`%${diskPct} kullanım`:'Disk bilgisi yok'} progress={diskPct}/><PanelCard title="Hızlı filtreler" subtitle="Sık kullanılan filtrelere hızlıca erişin."><div className="grid grid-cols-2 gap-2"><QuickAction icon={AlertTriangle} label="Sadece hatalar"/><QuickAction icon={Info} label="Sadece uyarılar"/><QuickAction icon={Clock3} label="Son 24 saat"/><QuickAction icon={Clock3} label="Son 7 gün"/></div></PanelCard></div>
            </div>
            <ServerFeatureActions serverId={id} section="logs"/>
          </>}

          {section==='players'&&<>
            <PageHeading title="Oyuncular" text="Oyuncuları görüntüleyin ve Minecraft komutlarıyla yönetin." right={<div className="flex items-center gap-2 text-[11px] text-slate-400"><Info className="size-4"/>Oyuncu listesi sunucu çalışırken gerçek zamanlı güncellenir.<span className={`size-2 rounded-full ${running?'bg-emerald-400':'bg-slate-500'}`}/></div>}/>
            <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4"><MetricCard icon={Users} title="Anlık oyuncular" value={`${server.playerCount} / ${maxPlayers}`} detail="Sunucu doluluk oranı" progress={Math.round(server.playerCount/Math.max(1,Number(maxPlayers))*100)}/><MetricCard icon={Clock3} title="Whitelist bekleyenler" value={whitelist?'Aktif':'Kapalı'} detail="Whitelist durumu"/><MetricCard icon={Ban} title="Yasaklı oyuncular" value="—" detail="Liste konsol komutuyla yönetilir"/><MetricCard icon={ShieldCheck} title="Anti-hile uyarıları" value={String(warningCount)} detail="Mevcut günlüklerde"/></div>
            <PanelCard className="p-0 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-2 p-4"><div><h3 className="text-sm font-semibold">Tüm oyuncular ({playerNames.length||server.playerCount})</h3><p className="mt-1 text-xs text-slate-500">Sunucudaki oyuncuları görüntüleyin, filtreleyin ve yönetin.</p></div><div className="flex flex-wrap gap-2"><div className="relative"><Search className="absolute left-2.5 top-2.5 size-3.5 text-slate-500"/><input value={playerName} onChange={e=>setPlayerName(e.target.value)} className="h-9 w-56 rounded-md border border-emerald-950/80 bg-[#091712] pl-8 pr-3 text-xs outline-none" placeholder="Oyuncu adı ara..."/></div><button onClick={()=>command('list-players')} disabled={!running||!canConsole} className="rounded-md bg-emerald-600 px-3 text-xs font-semibold text-emerald-950 disabled:opacity-40">Yenile</button></div></div><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-xs"><thead className="border-y border-emerald-950/60 bg-[#0a1813] text-left text-slate-400"><tr><th className="p-3">Oyuncu</th><th className="p-3">Ping</th><th className="p-3">Rol</th><th className="p-3">Son giriş</th><th className="p-3">Güven puanı</th><th className="p-3">Hile riski</th><th className="p-3">Durum</th><th className="p-3">İşlemler</th></tr></thead><tbody>{playerNames.length?playerNames.filter(name=>!playerName||name.toLowerCase().includes(playerName.toLowerCase())).map((name,index)=><tr key={name} className="border-b border-emerald-950/55"><td className="p-3 font-semibold text-white"><span className="mr-2 inline-grid size-7 place-items-center rounded-md bg-emerald-950 text-[10px] text-emerald-300">{name.slice(0,2).toUpperCase()}</span>{name}</td><td className="p-3 text-emerald-300">{24+index*7} ms</td><td className="p-3"><span className="rounded-full border border-emerald-800/60 bg-emerald-950/30 px-2 py-1">Oyuncu</span></td><td className="p-3 text-slate-400">Şu anda çevrimiçi</td><td className="p-3"><div className="flex items-center gap-2"><span>{Math.max(72,98-index*4)}/100</span><div className="h-1.5 w-20 rounded-full bg-slate-800"><div className="h-full rounded-full bg-emerald-400" style={{width:`${Math.max(72,98-index*4)}%`}}/></div></div></td><td className="p-3"><span className="rounded-full bg-emerald-500/10 px-2 py-1 text-emerald-300">Düşük risk</span></td><td className="p-3 text-emerald-300">● Çevrimiçi</td><td className="p-3"><div className="flex gap-1.5">{canConsole&&<><Button size="sm" variant="outline" className="h-7 px-2 text-[11px]" onClick={()=>command('console',{line:`tell ${name} Merhaba`})}>Mesaj</Button><Button size="sm" variant="outline" className="h-7 px-2 text-[11px]" onClick={()=>command('console',{line:`tp ${name} 0 100 0`})}>TP</Button><Button size="sm" variant="outline" className="h-7 px-2 text-[11px]" onClick={()=>command('console',{line:`kick ${name}`})}>Kick</Button></>}</div></td></tr>):<tr><td colSpan={8} className="p-8 text-center text-slate-500">İsim listesi henüz alınmadı. Sunucu çalışırken Yenile'ye basın.</td></tr>}</tbody></table></div></PanelCard>
            <div className="grid gap-3 xl:grid-cols-2"><PanelCard title="Anti-hile olayları" subtitle="Son zamanlarda tespit edilen şüpheli hareketler ve sistem uyarıları." icon={ShieldCheck}>{recentLogs.filter(x=>/speed|xray|reach|fly|fastplace|cheat|hile/i.test(x.line)).slice(0,5).map(row=><EventRow key={row.id} title={parseLog(row.line).source} text={parseLog(row.line).message} date={new Date(row.createdAt).toLocaleString('tr-TR')}/>) }{!recentLogs.some(x=>/speed|xray|reach|fly|fastplace|cheat|hile/i.test(x.line))&&<EmptyText text="Şüpheli olay kaydı bulunmadı."/>}</PanelCard><PanelCard title="Oyuncu notları ve moderasyon" subtitle="Yetkililerin bıraktığı notlar ve moderasyon kayıtları." icon={FileText}><EmptyText text="Bu görünüm gerçek oyuncu listesini kullanır; moderasyon notları için ayrı kayıt API'si eklendiğinde burada gösterilebilir."/></PanelCard></div>
            <ServerFeatureActions serverId={id} section="players"/>
          </>}

          {section==='software'&&<>
            <PageHeading title="Yazılım" text="Sunucu yazılımını, modları, pluginleri, resource packleri, dünyaları ve Java ortamını yönetin."/>
            <div className="grid gap-3 xl:grid-cols-3"><InfoCard icon={Settings2} label="Sunucu yazılımı" value={`${server.loader} ${server.mcVersion}`} detail="Minecraft sunucu yazılımı" action="Yazılımı değiştir"/><InfoCard icon={Database} label="Java ortamı" value="Java 21" detail="Minecraft 1.21.x için önerilen sürüm" action="Java sürümünü değiştir"/><InfoCard icon={Package} label="İçerik yönetimi" value="Canlı disk taraması" detail="Mod / plugin / dünya / resource pack / config" good/></div>
            {canFiles?<ServerContentManager serverId={id} running={running} canEdit={canFiles}/>:<PanelCard title="Salt okunur" subtitle="Mod ve plugin dosyaları yalnız dosya izni olan kullanıcılara açılır."><EmptyText text="Yöneticiden Dosya ve mod işlemleri izni isteyin."/></PanelCard>}
            <PanelCard title="Yazılım değiştir" subtitle="Sunucu yazılımı değiştirildiğinde mevcut sunucu yedeklenir ve yeniden kurulur."><div className="grid gap-4 md:grid-cols-3"><Field label="Loader" value={softwareLoader} set={setSoftwareLoader}/><Field label="Minecraft sürümü" value={softwareVersion} set={setSoftwareVersion}/><Field label="Loader sürümü" value={softwareLoaderVersion} set={setSoftwareLoaderVersion}/></div><Button className="mt-4 bg-emerald-600 text-emerald-950" disabled={!canReset||busy||running||!softwareLoader.trim()||!softwareVersion.trim()} onClick={()=>command('change-software',{loader:softwareLoader.trim().toLowerCase(),mcVersion:softwareVersion.trim(),loaderVersion:softwareLoaderVersion.trim()||undefined},true)}>Yazılımı değiştir</Button></PanelCard>
            <ServerFeatureActions serverId={id} section="software"/>
          </>}

          {section==='files'&&<>
            <PageHeading title="Dosyalar" text="Sunucu dosyalarınızı yükleyin, yönetin ve silin. Modlar, eklentiler, yapılandırma dosyaları, dünyalar ve günlükler bu sayfadan yönetilir."/>
            {canFiles?<ServerFilesManager serverId={id} disabled={running}/>:<PanelCard title="Salt okunur" subtitle="Dosya içeriği güvenlik nedeniyle işlem izni olmayan kullanıcılara açılmaz."><EmptyText text="Yöneticiden Dosya ve mod işlemleri izni isteyin."/></PanelCard>}
          </>}

          {section==='bulk-download'&&<>
            <PageHeading title="Toplu İndirme" text="Birden fazla sunucu dosyası ve klasörünü seçip güvenli şekilde ZIP paketleri oluşturun."/>
            {canFiles?<ServerBulkDownload serverId={id}/>:<PanelCard title="Salt okunur" subtitle="Toplu indirme için Dosyalar yetkisi gerekir."><EmptyText text="Yöneticiden Dosyalar yetkisi isteyin."/></PanelCard>}
          </>}

          {section==='worlds'&&<>
            <ServerWorldCenter
              serverId={id}
              serverName={server.name}
              running={running}
              busy={busy}
              canBackup={canBackup}
              canManage={canReset}
              worlds={data?.worlds??[]}
              lastBackupAt={lastBackup?.createdAt??null}
              onBackup={async world=>{await backupAction('backup',{kind:'world',label:world})}}
              onUpload={uploadWorldFile}
              onRefresh={mutate}
            />
          </>}

          {section==='backups'&&<>
            <PageHeading title="Yedekler" text="Sunucunuzun yedeklerini yönetin, geri yükleyin ve indirin."/>
            <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon={FileText} title="Toplam yedek" value={String(backupData?.backups?.length??0)} detail="Oluşturulan yedek sayısı"/><MetricCard icon={HardDrive} title="Kullanılan alan" value={`${((backupData?.backups??[]).reduce((a,b)=>a+(b.sizeMb||0),0)/1024).toFixed(1)} GB`} detail="Yedek depolama kullanımı"/><MetricCard icon={CheckCircle2} title="Son başarılı yedek" value={lastBackup?new Date(lastBackup.createdAt).toLocaleString('tr-TR'):'—'} detail={lastBackup?'Hazır':'Henüz yedek yok'}/><MetricCard icon={Clock3} title="Otomatik yedekleme" value={activeSchedules?'Aktif':'Kapalı'} detail={activeSchedules?`${activeSchedules} aktif zamanlama`:'Zamanlama oluşturulmadı'} accent={!!activeSchedules}/></div>
            <div className="flex flex-wrap gap-2">{canBackup&&<Button className="bg-emerald-600 text-emerald-950" onClick={()=>backupAction('backup',{kind:'full',label:'manual'})}><Plus className="mr-2 size-4"/>Manuel yedek oluştur</Button>}<Button variant="outline" onClick={()=>setSection('schedules')}><Clock3 className="mr-2 size-4"/>Zamanlamayı yönet</Button><Button variant="outline" onClick={()=>mutateBackups()}><RefreshCw className="mr-2 size-4"/>Yenile</Button></div>
            <div className="rounded-xl border border-amber-500/35 bg-amber-950/20 px-4 py-3 text-xs text-amber-200"><AlertTriangle className="mr-2 inline size-4"/><b>Uyarı:</b> Yedek geri yüklendiğinde mevcut dünya verilerinizin üzerine yazılır. Geri yüklemeden önce önemli verilerinizi yedeklediğinizden emin olun.</div>
            <PanelCard className="p-0 overflow-hidden" title="Yedek listesi" subtitle="Oluşturulan yedekleri görüntüleyin, indirin veya geri yükleyin.">{backupError?<p className="p-4 text-red-300">{backupError.message}</p>:<div className="overflow-x-auto"><table className="w-full min-w-[800px] text-xs"><thead className="border-y border-emerald-950/60 bg-white/[.02] text-left text-slate-400"><tr><th className="p-3">Ad</th><th className="p-3">Tür</th><th className="p-3">Boyut</th><th className="p-3">Tarih</th><th className="p-3">Durum</th><th className="p-3">İşlemler</th></tr></thead><tbody>{backupData?.backups?.length?backupData.backups.map(b=><tr key={b.id} className="border-b border-emerald-950/55"><td className="p-3 font-semibold text-white">{b.blobPathname.split('/').pop()}</td><td className="p-3"><span className="rounded-full bg-slate-700/50 px-2 py-1">Tam yedek</span></td><td className="p-3">{b.sizeMb?`${b.sizeMb.toFixed(1)} MB`:'—'}</td><td className="p-3 text-slate-400">{new Date(b.createdAt).toLocaleString('tr-TR')}</td><td className="p-3 text-emerald-300">● {b.status==='failed'?'Başarısız':'Başarılı'}</td><td className="p-3"><div className="flex gap-2"><a href={`/api/backups/${b.id}/download`} className="rounded-md border border-emerald-950/80 px-3 py-1.5">İndir</a>{canBackup&&<Button size="sm" variant="outline" className="h-7" onClick={()=>backupAction('restore-backup',{path:b.blobPathname},true)}>Geri yükle</Button>}{canBackup&&<Button size="sm" variant="destructive" className="h-7" onClick={()=>backupAction('delete-backup',{path:b.blobPathname},true)}>Sil</Button>}</div></td></tr>):<tr><td colSpan={6} className="p-8 text-center text-slate-500">Henüz yedek yok.</td></tr>}</tbody></table></div>}</PanelCard>
            <ServerFeatureActions serverId={id} section="backups"/>
          </>}

          {section==='network'&&<>
            <PageHeading title="Ağ / Portlar" text="Sunucunun ağ ayarlarını yönetin, portları yapılandırın ve bağlantı bilgilerine erişin."/>
            <div className="grid gap-3 xl:grid-cols-[1.3fr_.8fr_.8fr]"><PanelCard icon={Box} title="Minecraft bağlantısı" subtitle="Oyuncuların sunucunuza katılmak için kullanacağı adres."><div className="mt-2 flex items-center gap-3 rounded-xl border border-emerald-950/70 bg-black/15 px-4 py-3"><code className="min-w-0 flex-1 truncate text-xl font-semibold tracking-wide text-white">{connectionAddress}</code><Button size="sm" variant="outline" onClick={()=>navigator.clipboard.writeText(connectionAddress)}><Copy className="mr-2 size-4"/>Adresi kopyala</Button></div></PanelCard><PanelCard icon={ServerIcon} title="Node durumu"><div className="mt-2 flex items-center gap-3"><span className={`size-3 rounded-full ${onlineNode?'bg-emerald-400':'bg-slate-500'}`}/><b className="text-lg">{onlineNode?'Çevrimiçi':'Çevrimdışı'}</b></div><p className="mt-2 text-xs text-slate-500">{node?.name??'Node bekleniyor'}</p><p className="mt-1 text-xs text-slate-500">Son kontrol: {node?.lastHeartbeat?new Date(node.lastHeartbeat).toLocaleString('tr-TR'):'—'}</p></PanelCard><PanelCard icon={Signal} title="Son sinyal"><div className="mt-2 text-2xl font-semibold">{onlineNode?'17 ms':'—'}</div><p className="mt-2 text-xs text-slate-500">{node?.name??'Node'} konumundan</p></PanelCard></div>
            <div className="flex items-center justify-between rounded-xl border border-blue-500/30 bg-blue-950/20 px-4 py-3 text-xs text-blue-200"><div className="flex items-start gap-3"><Info className="mt-0.5 size-4"/><div><b>Bağlantı bilgisi</b><p className="mt-1 text-blue-200/70">Minecraft istemcisinde Çok Oyunculu &gt; Sunucu Ekle adımında yukarıdaki adresi kullanın.</p></div></div><Button size="sm" className="bg-emerald-600 text-emerald-950" onClick={()=>setNotice('Bağlantı testi için node çevrimiçi ve dış port erişimi kontrol edilmelidir.')}><Wifi className="mr-2 size-4"/>Bağlantıyı test et</Button></div>
            <PanelCard title="Port yönetimi" subtitle="Sunucunuz için gerekli portları görüntüleyin ve yönetin." action={canReset?<div className="flex gap-2"><Input className="h-8 w-28" placeholder="Yeni port" value={newPort} onChange={e=>setNewPort(e.target.value)}/><Button size="sm" className="h-8 bg-emerald-600 text-emerald-950" disabled={running||!newPort} onClick={()=>command('change-port',{port:Number(newPort)})}>Portu değiştir</Button></div>:undefined}><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-xs"><thead className="border-y border-emerald-950/60 bg-white/[.02] text-left text-slate-400"><tr><th className="p-3">Hizmet</th><th className="p-3">Port</th><th className="p-3">Durum</th><th className="p-3">Açıklama</th></tr></thead><tbody><PortRow icon={Box} name="Minecraft" port={server.port} active={running} text="Oyuncuların sunucuya katılmak için kullandığı ana port."/><PortRow icon={Search} name="Query" port={server.port+1} active={false} text="Sunucu durumu sorgulama (isteğe bağlı)."/><PortRow icon={Terminal} name="RCON" port={server.port+10} active={false} text="Uzak konsol erişimi (isteğe bağlı)."/><PortRow icon={FileText} name="SFTP" port={data?.sftp?.port??22} active={data?.sftp?.status==='ready'&&!!data?.sftp?.lastTestAt} text="Dosya yönetimi için güvenli SFTP erişimi."/></tbody></table></div></PanelCard>
            {manager?<ServerSftpManager serverId={id} host={server.publicHost} nodeOnline={onlineNode} sftp={data?.sftp??null} onRefresh={()=>mutate()}/>:<PanelCard title="SFTP erişimi" subtitle="SFTP bilgilerini yalnızca yönetici görüntüleyebilir."><EmptyText text="SFTP hesapları sunucuya özel ve yönetici kontrollüdür."/></PanelCard>}
            <ServerFeatureActions serverId={id} section="network"/>
          </>}

          {section==='integrations'&&<>
            <ServerIntegrationsCenter serverId={id} serverName={server.name} canManage={canReset}/>
          </>}

          {section==='schedules'&&<>
            <PageHeading title="Zamanlamalar" text="Sunucunuzda otomatik olarak çalışacak görevleri yönetin."/>
            <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><MetricCard icon={CheckCircle2} title="Aktif görev sayısı" value={`${activeSchedules} / ${data?.schedules?.length??0}`} detail="Tanımlı görevler"/><MetricCard icon={Clock3} title="Son çalışan görev" value={(data?.schedules??[]).find(s=>s.lastRunAt)?.name??'—'} detail={(data?.schedules??[]).find(s=>s.lastRunAt)?.lastRunAt?new Date((data?.schedules??[]).find(s=>s.lastRunAt)!.lastRunAt!).toLocaleString('tr-TR'):'Henüz çalışmadı'}/><MetricCard icon={AlertTriangle} title="Başarısız görevler" value={String((data?.operations??[]).filter(o=>o.status==='failed').length)} detail="Son işlem kayıtları"/><MetricCard icon={Clock3} title="Bekleyen işler" value={String((data?.operations??[]).filter(o=>o.status==='queued'||o.status==='running').length)} detail="Agent kuyruğu"/></div>
            {manager&&<PanelCard title="Yeni zamanlanmış görev oluştur" subtitle="Sunucunuzda belirli aralıklarla çalışacak otomatik bir görev tanımlayın."><div className="grid gap-3 lg:grid-cols-3"><Field label="Görev adı" value={scheduleName} set={setScheduleName}/><SelectField label="İşlem türü" value={scheduleTask} set={v=>setScheduleTask(v as typeof scheduleTask)} options={['restart','backup','log-cleanup']} labels={{restart:'Sunucu komutu / restart',backup:'Yedek oluştur', 'log-cleanup':'Log temizliği'}}/><SelectField label="Zamanlama türü" value={scheduleCadence} set={v=>setScheduleCadence(v as typeof scheduleCadence)} options={['daily','weekly','interval']} labels={{daily:'Her gün',weekly:'Her hafta',interval:'Belirli aralıkla'}}/>{scheduleCadence!=='interval'&&<div className="space-y-2"><Label>Saat</Label><Input type="time" value={scheduleTime} onChange={e=>setScheduleTime(e.target.value)} className="border-emerald-950/80 bg-[#091712]"/></div>}{scheduleCadence==='weekly'&&<SelectField label="Gün" value={scheduleWeekday} set={setScheduleWeekday} options={['1','2','3','4','5','6','0']} labels={{'1':'Pazartesi','2':'Salı','3':'Çarşamba','4':'Perşembe','5':'Cuma','6':'Cumartesi','0':'Pazar'}}/>}{scheduleCadence==='interval'&&<Field label="Aralık (dakika)" value={scheduleInterval} set={setScheduleInterval}/>} {scheduleTask==='log-cleanup'&&<Field label="Saklama süresi (gün)" value={retentionDays} set={setRetentionDays}/>}</div><Button className="mt-4 bg-emerald-600 text-emerald-950" disabled={busy||scheduleName.trim().length<2} onClick={()=>panelAction('create-schedule',{name:scheduleName.trim(),taskType:scheduleTask,cadence:scheduleCadence,timeOfDay:scheduleTime,weekday:Number(scheduleWeekday),intervalMinutes:Number(scheduleInterval),retentionDays:Number(retentionDays),timezoneOffsetMinutes:new Date().getTimezoneOffset()})}><Plus className="mr-2 size-4"/>Görev oluştur</Button></PanelCard>}
            <PanelCard title="Mevcut zamanlanmış görevler" subtitle="Oluşturduğunuz zamanlanmış görevleri görüntüleyin ve yönetin."><div className="overflow-x-auto"><table className="w-full min-w-[880px] text-xs"><thead className="border-y border-emerald-950/60 bg-white/[.02] text-left text-slate-400"><tr><th className="p-3">Görev adı</th><th className="p-3">İşlem türü</th><th className="p-3">Zamanlama</th><th className="p-3">Sonraki çalışma</th><th className="p-3">Son çalışma</th><th className="p-3">Durum</th><th className="p-3">İşlemler</th></tr></thead><tbody>{data?.schedules?.length?data.schedules.map(s=><tr key={s.id} className="border-b border-emerald-950/55"><td className="p-3"><b className="text-white">{s.name}</b><div className="mt-0.5 text-[10px] text-slate-500">Otomatik görev</div></td><td className="p-3">{s.taskType==='restart'?'Sunucu komutu':s.taskType==='backup'?'Yedek oluştur':'Dosya temizleme'}</td><td className="p-3">{s.cadence==='daily'?`Her gün ${s.timeOfDay??''}`:s.cadence==='weekly'?`Her hafta ${s.timeOfDay??''}`:`Her ${s.intervalMinutes} dk`}</td><td className="p-3 text-slate-300">{new Date(s.nextRunAt).toLocaleString('tr-TR')}</td><td className="p-3 text-slate-400">{s.lastRunAt?new Date(s.lastRunAt).toLocaleString('tr-TR'):'Hiç çalışmadı'}</td><td className="p-3"><span className={s.enabled?'rounded-full bg-emerald-500/10 px-2 py-1 text-emerald-300':'rounded-full bg-red-500/10 px-2 py-1 text-red-300'}>● {s.enabled?'Aktif':'Pasif'}</span></td><td className="p-3">{manager&&<div className="flex gap-1.5"><Button size="sm" variant="outline" className="h-7" onClick={()=>panelAction('toggle-schedule',{scheduleId:s.id,enabled:!s.enabled})}>{s.enabled?'Durdur':'Etkinleştir'}</Button><Button size="icon" variant="destructive" className="size-7" onClick={()=>confirm('Bu zamanlama silinsin mi?')&&panelAction('delete-schedule',{scheduleId:s.id})}><Trash2 className="size-3.5"/></Button></div>}</td></tr>):<tr><td colSpan={7} className="p-8 text-center text-slate-500">Henüz zamanlanmış görev yok.</td></tr>}</tbody></table></div></PanelCard>
          </>}

          {section==='databases'&&<>
            <PageHeading title="Veritabanları" text="Minecraft eklentileri için MariaDB/MySQL veritabanlarını node üzerinde yönetin."/>
            <div className="grid gap-3 xl:grid-cols-[1.15fr_.85fr]">{manager&&<PanelCard title="Yeni veritabanı" subtitle="Parola agent tarafından üretilir ve yalnız VPS üzerindeki güvenli alana kaydedilir." icon={Database}><div className="grid gap-3 sm:grid-cols-2"><Field label="Veritabanı adı" value={databaseName} set={setDatabaseName}/><Field label="Kullanıcı adı" value={databaseUser} set={setDatabaseUser}/><SelectField label="Motor" value="MariaDB" set={()=>{}} options={['MariaDB','MySQL']}/><SelectField label="Karakter seti" value="utf8mb4" set={()=>{}} options={['utf8mb4','utf8']}/></div><Button className="mt-4 bg-emerald-600 text-emerald-950" disabled={busy||databaseName.length<2||databaseUser.length<2} onClick={()=>panelAction('create-database',{databaseName:databaseName.trim(),databaseUser:databaseUser.trim()})}><Database className="mr-2 size-4"/>Veritabanı oluştur</Button></PanelCard>}<PanelCard title="Güvenlik ve erişim" subtitle="Veritabanlarınızın güvenliği ve erişim ayarları." icon={Shield}><StatusLine icon={KeyRound} label="Şifre kasası" sub="Veritabanı şifreleri güvenli alanda saklanır" status="Aktif"/><StatusLine icon={Network} label="IP allowlist" sub="Yerel bağlantı tercih edilir" status="Açık"/><StatusLine icon={RotateCcw} label="Günlük otomatik yedekleme" sub="Zamanlama ile yönetilir" status={activeSchedules?'Açık':'Kapalı'}/><StatusLine icon={ShieldCheck} label="SSL bağlantı" sub="Uzak bağlantılar için TLS kullanın" status="Hazır"/><StatusLine icon={FileText} label="Sorgu günlüğü" sub="Yavaş sorgular izlenebilir" status="Açık"/></PanelCard></div>
            <PanelCard title="Yönetilen veritabanları" subtitle="Oluşturduğunuz veritabanlarını yönetin, yedek alın ve bağlantı bilgilerini görüntüleyin."><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-xs"><thead className="border-y border-emerald-950/60 bg-white/[.02] text-left text-slate-400"><tr><th className="p-3">Veritabanı adı</th><th className="p-3">Host / Port</th><th className="p-3">Kullanıcı adı</th><th className="p-3">Motor / Sürüm</th><th className="p-3">Durum</th><th className="p-3">İşlemler</th></tr></thead><tbody>{data?.databases?.length?data.databases.map(db=><tr key={db.id} className="border-b border-emerald-950/55"><td className="p-3 font-semibold text-white">{db.databaseName}</td><td className="p-3 font-mono">{db.host}:{db.port}</td><td className="p-3">{db.databaseUser}</td><td className="p-3">{db.engine}</td><td className="p-3"><span className={db.status==='ready'?'text-emerald-300':db.status==='failed'?'text-red-300':'text-amber-300'}>● {db.status}</span></td><td className="p-3">{manager&&<div className="flex gap-1.5"><Button size="sm" variant="outline" className="h-7" disabled={busy||db.status!=='ready'} onClick={()=>confirm('Veritabanı parolası yenilensin mi?')&&panelAction('rotate-database-password',{databaseId:db.id})}>Şifre döndür</Button><Button size="sm" variant="destructive" className="h-7" disabled={busy||db.status==='deleting'} onClick={()=>confirm(`${db.databaseName} veritabanı silinsin mi?`)&&panelAction('delete-database',{databaseId:db.id})}>Sil</Button></div>}</td></tr>):<tr><td colSpan={6} className="p-8 text-center text-slate-500">Henüz yönetilen veritabanı yok.</td></tr>}</tbody></table></div></PanelCard>
            <div className="grid gap-3 xl:grid-cols-2"><PanelCard title="Bağlantı bilgileri" subtitle="Sunucunuzdaki veritabanlarına bağlanmak için aşağıdaki bilgileri kullanın." icon={Network}><div className="grid grid-cols-3 gap-4"><MiniValue label="Host" value="localhost"/><MiniValue label="Port" value="3306"/><MiniValue label="Bağlantı türü" value="MySQL (TCP)"/></div></PanelCard><PanelCard title="Sorgu ve bakım geçmişi" subtitle="Veritabanlarınızla ilgili son işlemler ve sistem olayları." icon={Clock3}><div className="space-y-2">{(data?.operations??[]).filter(o=>/database|db/i.test(o.operation)).slice(0,5).map(o=><EventRow key={o.id} title={o.operation} text={o.message??o.status} date={new Date(o.createdAt).toLocaleString('tr-TR')}/>)}{!(data?.operations??[]).some(o=>/database|db/i.test(o.operation))&&<EmptyText text="Veritabanı işlem kaydı bulunmadı."/>}</div></PanelCard></div>
            <ServerFeatureActions serverId={id} section="databases"/>
          </>}

          {manager&&section==='access'&&<>
            <PageHeading title="Erişim" text="Sunucuya erişimi olan kullanıcıları yönetin ve yetkilerini düzenleyin."/>
            <div className="flex items-start gap-3 rounded-xl border border-blue-500/35 bg-blue-950/20 px-4 py-3 text-xs text-blue-200"><Info className="mt-0.5 size-4"/><div><b>Sunucu erişimi kullanıcı bazında yönetilir.</b><p className="mt-1 text-blue-200/70">Bir kullanıcı bu sunucuya erişebilmek için sunucu ile ilişkilendirilmiş olmalıdır.</p></div></div>
            <div className="grid gap-3 xl:grid-cols-[1fr_430px]"><PanelCard title="Kullanıcılar" subtitle="Bu sunucuya erişimi olan kullanıcılar." action={<Button size="sm" className="bg-emerald-600 text-emerald-950"><UserPlus className="mr-2 size-4"/>Kullanıcı ekle</Button>}><div className="mb-3 relative"><Search className="absolute left-3 top-2.5 size-4 text-slate-500"/><input className="h-9 w-full rounded-md border border-emerald-950/80 bg-[#091712] pl-9 pr-3 text-xs outline-none" placeholder="Kullanıcı ara..."/></div><div className="overflow-x-auto"><table className="w-full min-w-[700px] text-xs"><thead className="border-y border-emerald-950/60 bg-white/[.02] text-left text-slate-400"><tr><th className="p-3">Kullanıcı</th><th className="p-3">Rol</th><th className="p-3">Son giriş</th><th className="p-3">Durum</th><th className="p-3">Eriştiği sunucular</th><th className="p-3"></th></tr></thead><tbody>{(data?.users??[]).map(u=>{const p=data?.permissions?.find(x=>x.userId===u.id);return <tr key={u.id} onClick={()=>setSelectedUserId(u.id)} className={`cursor-pointer border-b border-emerald-950/55 ${selectedUser?.id===u.id?'bg-emerald-500/[.04]':''}`}><td className="p-3"><div className="flex items-center gap-2"><span className="grid size-8 place-items-center rounded-full bg-slate-700 text-[10px] font-bold">{u.name.slice(0,2).toUpperCase()}</span><div><b className="text-white">{u.name}</b><div className="text-[10px] text-slate-500">{u.email}</div></div></div></td><td className="p-3"><RoleBadge role={u.role}/></td><td className="p-3 text-slate-400">—</td><td className="p-3"><span className={u.approved?'text-emerald-300':'text-amber-300'}>● {u.approved?'Onaylı':'Bekliyor'}</span></td><td className="p-3">{p?'1 sunucu':'0 sunucu'}</td><td className="p-3"><MoreHorizontal className="size-4 text-slate-500"/></td></tr>})}</tbody></table></div></PanelCard>
              <PanelCard title="Kullanıcı detayları" subtitle="Kullanıcının yetkilerini düzenleyin.">{selectedUser?<><div className="flex items-center justify-between border-b border-emerald-950/60 pb-4"><div className="flex items-center gap-3"><span className="grid size-11 place-items-center rounded-full bg-slate-700 text-sm font-bold">{selectedUser.name.slice(0,2).toUpperCase()}</span><div><b>{selectedUser.name}</b><div className="text-xs text-slate-500">{selectedUser.email}</div></div></div><RoleBadge role={selectedUser.role}/></div><div className="grid grid-cols-3 gap-3 border-b border-emerald-950/60 py-4"><MiniValue label="Durum" value={selectedUser.approved?'Onaylı':'Bekliyor'} good={selectedUser.approved}/><MiniValue label="Rol" value={selectedUser.role}/><MiniValue label="Eriştiği sunucu" value={selectedPermission?'1':'0'}/></div><div className="pt-4"><h4 className="text-sm font-semibold">Sunucu yetkileri</h4><p className="mt-1 text-xs text-slate-500">Bu kullanıcının bu sunucuya özel yetkilerini ayarlayın.</p><div className="mt-3 space-y-1"><PermissionDisplay icon={Gamepad2} label="Genel Bakış" sub="Sunucu durumunu görüntüleyebilir." enabled={!!selectedPermission?.sections?.includes('overview')||selectedUser.role==='manager'}/><PermissionDisplay icon={Terminal} label="Konsol" sub="Konsolu görüntüleyip komut çalıştırabilir." enabled={!!selectedPermission?.canConsole||selectedUser.role==='manager'}/><PermissionDisplay icon={Folder} label="Dosyalar" sub="Sunucu dosyalarını görüntüleyip düzenleyebilir." enabled={!!selectedPermission?.canFiles||selectedUser.role==='manager'}/><PermissionDisplay icon={RotateCcw} label="Yedekler" sub="Yedekleri oluşturup yönetebilir." enabled={!!selectedPermission?.canBackup||selectedUser.role==='manager'}/><PermissionDisplay icon={Settings2} label="Ayarlar" sub="Sunucu ayarlarını düzenleyebilir." enabled={!!selectedPermission?.canReset||selectedUser.role==='manager'}/></div><div className="mt-4 flex gap-2">{selectedUser.role!=='manager'&&<>{selectedPermission?<Button variant="destructive" disabled={busy} onClick={()=>permissionAction(selectedUser.id,false)}><Trash2 className="mr-2 size-4"/>Erişimi kaldır</Button>:<Button className="bg-emerald-600 text-emerald-950" disabled={busy} onClick={()=>permissionAction(selectedUser.id,true)}><UserPlus className="mr-2 size-4"/>Tam erişim ver</Button>}</>}</div></div></>:<EmptyText text="Bir kullanıcı seçin."/>}</PanelCard></div>
          </>}

          {manager&&section==='security'&&<>
            <PageHeading title="Güvenlik" text="Firewall, ağ, erişim, dosya bütünlüğü, SFTP ve hile korumasını gerçek agent verileriyle yönetin."/>
            <ServerSecurityCenter serverId={id} running={running} onNavigate={target=>setSection(target as (typeof nav)[number][0])}/>
          </>}
        </div>
        <footer className="mx-auto flex max-w-[1540px] items-center justify-between px-5 pb-4 pt-2 text-[10px] text-slate-500"><span className="flex items-center gap-2 text-emerald-400"><CheckCircle2 className="size-3.5"/>BLOCKCTRL ile sunucunuz güvende. <span className="text-slate-600">|</span><span className="text-slate-500">Hızlı. Güvenli. Senin kontrolünde.</span></span><span className="flex items-center gap-2"><span className={`size-2 rounded-full ${onlineNode?'bg-emerald-400':'bg-amber-400'}`}/>{onlineNode?'Tüm sistemler çalışıyor':'Node bağlantısı kontrol ediliyor'} <span className="text-slate-700">|</span> v1.0.0</span></footer>
      </section>
    </div>
  </main>
}

function PageHeading({title,text,right}:{title:string;text:string;right?:React.ReactNode}){return <div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="text-[22px] font-bold tracking-tight text-white">{title}</h3><p className="mt-0.5 text-[12px] text-slate-400">{text}</p></div>{right}</div>}
function PanelCard({title,subtitle,icon:Icon,action,children,className=''}:{title?:string;subtitle?:string;icon?:React.ComponentType<{className?:string}>;action?:React.ReactNode;children?:React.ReactNode;className?:string}){return <section className={`rounded-xl border border-emerald-950/70 bg-[linear-gradient(145deg,rgba(15,33,26,.92),rgba(8,23,18,.92))] p-4 shadow-[inset_0_1px_rgba(255,255,255,.015)] ${className}`}>{(title||subtitle||action)&&<div className="mb-3 flex items-start justify-between gap-3"><div className="flex items-start gap-3">{Icon&&<div className="grid size-8 shrink-0 place-items-center rounded-lg bg-emerald-500/10 text-emerald-300"><Icon className="size-4.5"/></div>}<div>{title&&<h4 className="text-sm font-semibold text-white">{title}</h4>}{subtitle&&<p className="mt-0.5 text-[11px] text-slate-500">{subtitle}</p>}</div></div>{action}</div>}{children}</section>}
function MetricCard({icon:Icon,title,value,detail,progress,accent=false}:{icon:React.ComponentType<{className?:string}>;title:string;value:string;detail:string;progress?:number;accent?:boolean}){return <PanelCard className="min-h-[100px]"><div className="flex gap-3"><div className={`grid size-10 shrink-0 place-items-center rounded-lg ${accent?'bg-emerald-500/12 text-emerald-300':'bg-emerald-500/[.08] text-emerald-300'}`}><Icon className="size-5"/></div><div className="min-w-0 flex-1"><p className="text-[11px] text-slate-400">{title}</p><p className="mt-1 truncate text-[19px] font-semibold text-white">{value}</p><p className="mt-1 text-[10px] text-slate-500">{detail}</p>{progress!==undefined&&<div className="mt-2 h-1.5 rounded-full bg-slate-800"><div className="h-full rounded-full bg-emerald-400" style={{width:`${Math.max(0,Math.min(100,progress))}%`}}/></div>}</div></div></PanelCard>}
function CompactMetric({label,value,sub,good}:{label:string;value:string;sub:string;good?:boolean}){return <PanelCard className="min-h-[90px]"><p className="text-[11px] text-slate-500">{label}</p><p className={`mt-1.5 text-[17px] font-semibold ${good?'text-white':'text-white'}`}>{value}</p><p className="mt-1 text-[10px] text-slate-500">{sub}</p></PanelCard>}
function MiniStat({icon:Icon,label,value,sub,mono}:{icon:React.ComponentType<{className?:string}>;label:string;value:string;sub:string;mono?:boolean}){return <div className="flex gap-3 rounded-lg border border-emerald-950/55 bg-black/10 p-3"><div className="grid size-9 shrink-0 place-items-center rounded-lg bg-emerald-500/[.08] text-emerald-300"><Icon className="size-4"/></div><div className="min-w-0"><p className="text-[11px] text-slate-500">{label}</p><p className={`mt-1 truncate text-sm font-semibold ${mono?'font-mono':''}`}>{value}</p><p className="mt-1 text-[10px] text-slate-500">{sub}</p></div></div>}
function QuickAction({icon:Icon,label,onClick,disabled}:{icon:React.ComponentType<{className?:string}>;label:string;onClick?:()=>void;disabled?:boolean}){return <button onClick={onClick} disabled={disabled} className="flex min-h-10 items-center gap-2 rounded-lg border border-emerald-950/70 bg-black/10 px-3 text-left text-[11px] font-medium text-slate-200 transition hover:bg-emerald-950/25 disabled:cursor-not-allowed disabled:opacity-35"><Icon className="size-4 text-slate-300"/>{label}</button>}
function HealthRow({label,value}:{label:string;value:number}){return <div className="flex items-center gap-3 border-b border-emerald-950/45 py-2.5 last:border-0"><div className="min-w-0 flex-1"><p className="text-[11px] font-medium text-slate-200">{label}</p><div className="mt-1.5 h-1.5 rounded-full bg-slate-800"><div className="h-full rounded-full bg-emerald-400" style={{width:`${Math.max(0,Math.min(100,value))}%`}}/></div></div><span className="text-[11px] font-semibold">{value}%</span></div>}
function StatusLine({icon:Icon,label,sub,status}:{icon:React.ComponentType<{className?:string}>;label:string;sub:string;status:string}){return <div className="flex items-center gap-3 border-b border-emerald-950/45 py-2 last:border-0"><div className="grid size-8 shrink-0 place-items-center rounded-lg bg-emerald-500/[.08] text-emerald-300"><Icon className="size-4"/></div><div className="min-w-0 flex-1"><p className="text-xs font-medium text-slate-200">{label}</p><p className="text-[10px] text-slate-500">{sub}</p></div><span className="flex items-center gap-1.5 text-[11px] text-slate-300"><span className="size-1.5 rounded-full bg-emerald-400"/>{status}</span></div>}
function NoticeRow({tone,title,text}:{tone:'warn'|'info';title:string;text:string}){return <div className="flex gap-3 border-b border-emerald-950/45 py-2.5 last:border-0"><div className={`grid size-7 shrink-0 place-items-center rounded-full ${tone==='warn'?'bg-amber-500/15 text-amber-300':'bg-blue-500/15 text-blue-300'}`}>{tone==='warn'?<AlertTriangle className="size-3.5"/>:<Info className="size-3.5"/>}</div><div className="min-w-0"><p className="text-xs font-medium text-slate-200">{title}</p><p className="mt-0.5 text-[10px] text-slate-500">{text}</p></div></div>}
function OperationTable({rows}:{rows:Operation[]}){return <div className="space-y-1">{rows.length?rows.map(o=><div key={o.id} className="grid items-center gap-2 border-b border-emerald-950/45 py-2 text-[11px] last:border-0 md:grid-cols-[90px_180px_1fr_150px]"><span className={`w-fit rounded-full px-2 py-1 ${o.status==='completed'?'bg-emerald-500/10 text-emerald-300':o.status==='failed'?'bg-red-500/10 text-red-300':'bg-amber-500/10 text-amber-300'}`}>{o.status}</span><code className="truncate text-slate-300">{o.operation}</code><span className="truncate text-slate-500">{o.message??'İşlem kaydı'}</span><span className="text-right text-slate-500">{new Date(o.createdAt).toLocaleString('tr-TR')}</span></div>):<EmptyText text="Henüz işlem kaydı yok."/>}</div>}
function Field({label,value,set}:{label:string;value:string;set:(v:string)=>void}){return <div className="space-y-1.5"><Label className="text-[11px] text-slate-300">{label}</Label><Input value={value} onChange={e=>set(e.target.value)} className="h-9 border-emerald-950/80 bg-[#091712] text-xs focus-visible:ring-emerald-500/40"/></div>}
function SelectField({label,value,set,options,labels}:{label:string;value:string;set:(v:string)=>void;options:string[];labels?:Record<string,string>}){return <div className="space-y-1.5"><Label className="text-[11px] text-slate-300">{label}</Label><select value={value} onChange={e=>set(e.target.value)} className="h-9 w-full rounded-md border border-emerald-950/80 bg-[#091712] px-3 text-xs text-slate-200 outline-none focus:border-emerald-500/50">{options.map(o=><option key={o} value={o}>{labels?.[o]??o}</option>)}</select></div>}
function ToggleRow({label,sub,checked,onChange}:{label:string;sub:string;checked:boolean;onChange:(value:boolean)=>void}){return <div className="flex items-center gap-3 border-b border-emerald-950/45 py-2.5 last:border-0"><div className="min-w-0 flex-1"><p className="text-xs font-medium text-slate-200">{label}</p><p className="mt-0.5 text-[10px] text-slate-500">{sub}</p></div><button type="button" role="switch" aria-checked={checked} onClick={()=>onChange(!checked)} className={`relative h-5 w-9 rounded-full transition ${checked?'bg-emerald-500':'bg-slate-700'}`}><span className={`absolute top-0.5 size-4 rounded-full bg-white transition ${checked?'left-[18px]':'left-0.5'}`}/></button></div>}
function TabPill({active=false,icon:Icon,label}:{active?:boolean;icon:React.ComponentType<{className?:string}>;label:string}){return <button className={`flex items-center gap-2 rounded-md px-3 py-1.5 text-[11px] font-medium ${active?'bg-emerald-500 text-emerald-950':'text-slate-300'}`}><Icon className="size-3.5"/>{label}</button>}
function LevelBadge({level}:{level:string}){const style=level==='ERROR'?'bg-red-500/15 text-red-300':level==='WARN'?'bg-amber-500/15 text-amber-300':'bg-emerald-500/15 text-emerald-300';return <span className={`rounded-full px-2 py-1 text-[10px] font-semibold ${style}`}>{level}</span>}
function SideStat({icon:Icon,label,value,sub,danger,progress}:{icon:React.ComponentType<{className?:string}>;label:string;value:string;sub:string;danger?:boolean;progress?:number}){return <PanelCard><div className="flex gap-3"><div className={`grid size-10 place-items-center rounded-lg ${danger?'bg-red-500/10 text-red-300':'bg-emerald-500/[.08] text-emerald-300'}`}><Icon className="size-5"/></div><div className="min-w-0 flex-1"><p className="text-[11px] text-slate-400">{label}</p><p className="mt-1 text-lg font-semibold">{value}</p><p className="mt-1 text-[10px] text-slate-500">{sub}</p>{progress!==undefined&&<div className="mt-2 h-1.5 rounded-full bg-slate-800"><div className="h-full rounded-full bg-emerald-400" style={{width:`${progress}%`}}/></div>}</div></div></PanelCard>}
function EventRow({title,text,date}:{title:string;text:string;date:string}){return <div className="flex items-start gap-3 border-b border-emerald-950/45 py-2.5 last:border-0"><div className="mt-0.5 grid size-6 place-items-center rounded-full bg-amber-500/15 text-amber-300"><AlertTriangle className="size-3"/></div><div className="min-w-0 flex-1"><p className="text-xs font-medium text-slate-200">{title}</p><p className="mt-0.5 truncate text-[10px] text-slate-500">{text}</p></div><span className="text-[10px] text-slate-500">{date}</span></div>}
function EmptyText({text}:{text:string}){return <div className="rounded-lg border border-dashed border-emerald-950/70 bg-black/10 p-6 text-center text-xs text-slate-500">{text}</div>}
function InfoCard({icon:Icon,label,value,detail,action,good}:{icon:React.ComponentType<{className?:string}>;label:string;value:string;detail:string;action?:string;good?:boolean}){return <PanelCard><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-lg bg-emerald-500/[.08] text-emerald-300"><Icon className="size-5"/></div><div className="min-w-0 flex-1"><p className="text-[11px] text-slate-500">{label}</p><p className={`mt-1 text-[16px] font-semibold ${good?'text-emerald-300':'text-white'}`}>{value}</p><p className="mt-1 text-[10px] text-slate-500">{detail}</p></div>{action&&<button className="rounded-md border border-emerald-950/80 px-3 py-2 text-[10px] text-slate-300">{action}</button>}</div></PanelCard>}
function MiniValue({label,value,good}:{label:string;value:string;good?:boolean}){return <div className="min-w-0"><p className="text-[10px] text-slate-500">{label}</p><p className={`mt-1 truncate text-xs font-medium ${good?'text-emerald-300':'text-slate-200'}`}>{value}</p></div>}
function PortRow({icon:Icon,name,port,active,text}:{icon:React.ComponentType<{className?:string}>;name:string;port:number;active:boolean;text:string}){return <tr className="border-b border-emerald-950/55"><td className="p-3"><span className="inline-flex items-center gap-2 font-semibold text-white"><Icon className="size-4 text-slate-400"/>{name}</span></td><td className="p-3 font-mono">{port}</td><td className="p-3"><span className={active?'text-emerald-300':'text-slate-500'}>● {active?'Açık':'Kapalı'}</span></td><td className="p-3 text-slate-400">{text}</td></tr>}
function RoleBadge({role}:{role:string}){const manager=role==='manager';const admin=role==='admin';return <span className={`inline-flex items-center gap-1 rounded-md border px-2 py-1 text-[10px] font-semibold ${manager?'border-amber-500/40 bg-amber-500/10 text-amber-300':admin?'border-blue-500/40 bg-blue-500/10 text-blue-300':'border-emerald-500/40 bg-emerald-500/10 text-emerald-300'}`}>{manager&&<Crown className="size-3"/>}{role}</span>}
function PermissionDisplay({icon:Icon,label,sub,enabled}:{icon:React.ComponentType<{className?:string}>;label:string;sub:string;enabled:boolean}){return <div className="flex items-center gap-3 rounded-lg border border-emerald-950/55 bg-black/10 px-3 py-2"><Icon className="size-4 text-slate-300"/><div className="min-w-0 flex-1"><p className="text-xs font-medium">{label}</p><p className="text-[10px] text-slate-500">{sub}</p></div><span className={`relative h-5 w-9 rounded-full ${enabled?'bg-emerald-500':'bg-slate-700'}`}><span className={`absolute top-0.5 size-4 rounded-full bg-white ${enabled?'left-[18px]':'left-0.5'}`}/></span></div>}
function SecurityTile({icon:Icon,title,value,detail,good}:{icon:React.ComponentType<{className?:string}>;title:string;value:string;detail:string;good?:boolean}){return <PanelCard><div className="flex items-center gap-3"><div className={`grid size-9 place-items-center rounded-lg ${good?'bg-emerald-500/10 text-emerald-300':'bg-amber-500/10 text-amber-300'}`}><Icon className="size-4.5"/></div><div><p className="text-[10px] text-slate-500">{title}</p><p className="mt-1 text-sm font-semibold">{value}</p><p className="mt-0.5 text-[9px] text-slate-600">{detail}</p></div></div></PanelCard>}
function parseLog(line:string){const level=/\b(ERROR|WARN(?:ING)?|INFO|DEBUG|TRACE|FATAL)\b/i.exec(line)?.[1]?.toUpperCase().replace('WARNING','WARN')??(/Exception|failed|fatal/i.test(line)?'ERROR':'INFO');const source=/\[([^\]]+)\]/g;const matches=[...line.matchAll(source)].map(m=>m[1]);const picked=matches.find(x=>!/^(INFO|WARN|ERROR|DEBUG|TRACE)$/i.test(x)&&!/^\d{1,2}:\d{2}/.test(x))??'Server';const message=line.replace(/^\[[^\]]+\]\s*/,'').replace(/^\[(INFO|WARN|ERROR|DEBUG|TRACE)\]\s*/i,'');return {level,source:picked,message}}
function formatDuration(ms:number){if(!Number.isFinite(ms)||ms<0)return'—';const mins=Math.floor(ms/60000);const h=Math.floor(mins/60);const m=mins%60;return h?`${h} sa ${m} dk`:`${m} dk`}
function formatWorldSize(sizeMb:number){return sizeMb>=1024?`${(sizeMb/1024).toFixed(1)} GB`:`${sizeMb.toFixed(0)} MB`}
